import React, { useState } from 'react';

const ContentManagementTab = () => {
  const [searchBoard, setSearchBoard] = useState('');
  const [searchKeyword, setSearchKeyword] = useState('');
  const [searchNickname, setSearchNickname] = useState('');

  // 가상의 비활성화된 게시글
  const [inactivePosts, setInactivePosts] = useState([
    { id: 1, title: '부적절한 내용의 게시글', board: '리뷰', author: '문제유저1', status: '비활성화' },
    { id: 2, title: '스팸성 홍보 글', board: '사찰정보', author: '광고꾼', status: '비활성화' },
  ]);

  // 가상의 비활성화된 댓글
  const [inactiveComments, setInactiveComments] = useState([
    { id: 1, content: '욕설 댓글', board: '리뷰', author: '악플러1', status: '비활성화' },
    { id: 2, content: '개인정보 침해 댓글', board: '사찰정보', author: '정보유출자', status: '비활성화' },
  ]);

  const handleSearch = (e) => {
    e.preventDefault();
    // 여기에 실제 검색 API 호출 로직
    alert(`콘텐츠 검색! 게시판: ${searchBoard}, 키워드: "${searchKeyword}", 닉네임: "${searchNickname}" (API 연동 필요)`);
  };

  const handlePostAction = (postId, actionType) => {
    // 게시글 활성화/삭제 API 호출 로직
    const post = inactivePosts.find(p => p.id === postId);
    if (!post) return;

    if (actionType === '활성화') {
      alert(`게시글 "${post.title}"을 활성화합니다. (API 연동 필요)`);
      setInactivePosts(inactivePosts.filter(p => p.id !== postId)); // 목록에서 제거
    } else if (actionType === '삭제') {
      if (window.confirm(`게시글 "${post.title}"을 정말 삭제하시겠습니까?`)) {
        alert(`게시글 "${post.title}"을 삭제합니다. (API 연동 필요)`);
        setInactivePosts(inactivePosts.filter(p => p.id !== postId)); // 목록에서 제거
      }
    }
  };

  const handleCommentAction = (commentId, actionType) => {
    // 댓글 활성화/삭제 API 호출 로직
    const comment = inactiveComments.find(c => c.id === commentId);
    if (!comment) return;

    if (actionType === '활성화') {
      alert(`댓글 "${comment.content}"을 활성화합니다. (API 연동 필요)`);
      setInactiveComments(inactiveComments.filter(c => c.id !== commentId));
    } else if (actionType === '삭제') {
      if (window.confirm(`댓글 "${comment.content}"을 정말 삭제하시겠습니까?`)) {
        alert(`댓글 "${comment.content}"을 삭제합니다. (API 연동 필요)`);
        setInactiveComments(inactiveComments.filter(c => c.id !== commentId));
      }
    }
  };

  return (
    <div className="tab-content-section content-management-tab">
      <h3 className="tab-content-title">콘텐츠 관리 🛡️</h3>
      <form onSubmit={handleSearch} className="search-form">
        <select value={searchBoard} onChange={(e) => setSearchBoard(e.target.value)}>
          <option value="">게시판 선택</option>
          <option value="사찰정보">사찰정보</option>
          <option value="리뷰">리뷰</option>
        </select>
        <input
          type="text"
          placeholder="검색 키워드 (제목/내용)"
          value={searchKeyword}
          onChange={(e) => setSearchKeyword(e.target.value)}
        />
        <input
          type="text"
          placeholder="작성자 닉네임"
          value={searchNickname}
          onChange={(e) => setSearchNickname(e.target.value)}
        />
        <button type="submit" className="search-button">검색</button>
      </form>

      <h4>비활성화 게시글 목록 ({inactivePosts.length}개)</h4>
      <div className="post-list">
        {inactivePosts.length > 0 ? (
          inactivePosts.map(post => (
            <div key={post.id} className="post-item">
              <span className="post-title">[{post.board}] {post.title} (작성자: {post.author})</span>
              <div>
                <button className="action-button" onClick={() => handlePostAction(post.id, '활성화')}>활성화</button>
                <button className="action-button delete-button" onClick={() => handlePostAction(post.id, '삭제')}>삭제</button>
              </div>
            </div>
          ))
        ) : (
          <p>비활성화된 게시글이 없어요. ✨</p>
        )}
      </div>

      <h4 style={{marginTop: '40px'}}>비활성화 댓글 목록 ({inactiveComments.length}개)</h4>
      <div className="comment-list">
        {inactiveComments.length > 0 ? (
          inactiveComments.map(comment => (
            <div key={comment.id} className="comment-item">
              <span className="comment-content">
                [{comment.board}] {comment.content} (작성자: {comment.author})
              </span>
              <div>
                <button className="action-button" onClick={() => handleCommentAction(comment.id, '활성화')}>활성화</button>
                <button className="action-button delete-button" onClick={() => handleCommentAction(comment.id, '삭제')}>삭제</button>
              </div>
            </div>
          ))
        ) : (
          <p>비활성화된 댓글이 없어요. ✨</p>
        )}
      </div>
    </div>
  );
};

export default ContentManagementTab;
